<script lang="ts">
 import {onMount,onDestroy,createEventDispatcher,tick} from 'svelte';import {IntegrationCatalogClient,IntegrationCatalogError,INTEGRATION_STATUSES,integrationLabel,catalogText,type IntegrationConnector,type IntegrationCatalog,type IntegrationStatus} from './integration-catalog';import '../automations/automations.css';
 export let companyId:string;export let actorId:string;export let accessSignal:AbortSignal;
 const dispatch=createEventDispatcher<{close:void;denied:{status:number}}>();let detailElement:HTMLElement|undefined;
 let mounted=false,scope='',watched:AbortSignal|undefined,client:IntegrationCatalogClient|undefined,generation=0,session='',loading=true,error='',catalog:IntegrationCatalog|null=null,query='',status:'ALL'|IntegrationStatus='ALL',selectedId='',operationQuery='',shown=60;
 $: connectors=catalog?.connectors||[];
 $: filtered=connectors.filter(c=>(status==='ALL'||c.executionStatus===status)&&(c.title+' '+c.description+' '+c.operations.map(o=>o.title+' '+(o.resource||'')+' '+(o.description||'')).join(' ')).toLowerCase().includes(query.toLowerCase())).sort((a,b)=>a.title.localeCompare(b.title));
 $: selected=connectors.find(c=>c.id===selectedId)||null;
 $: operations=selected?.operations.filter(o=>(o.title+' '+(o.resource||'')+' '+(o.description||'')).toLowerCase().includes(operationQuery.toLowerCase()))||[];
 $: if(mounted&&(scope!==companyId+'\0'+actorId||watched!==accessSignal)){reset();scope=companyId+'\0'+actorId;watched=accessSignal;watched.addEventListener('abort',lost,{once:true});if(watched.aborted)lost();else{session=localStorage.getItem('token')||'';client=new IntegrationCatalogClient(companyId,()=>localStorage.getItem('token')||'',watched);void load();}}
 function reset(){generation++;client?.close();client=undefined;watched?.removeEventListener('abort',lost);catalog=null;loading=true;error='';query='';status='ALL';selectedId='';operationQuery='';shown=60;}
 function lost(){reset();loading=false;dispatch('close');}
 async function load(){if(!client)return;const n=generation,current=client;loading=true;error='';try{const value=await current.catalog();if(n===generation)catalog=value;}catch(cause){if(n!==generation)return;if(cause instanceof IntegrationCatalogError&&(cause.status===401||cause.status===403)){lost();dispatch('denied',{status:cause.status});return;}error=cause instanceof Error?cause.message:'The integration catalog could not be loaded.';}finally{if(n===generation)loading=false;}}
 async function choose(connector:IntegrationConnector){selectedId=connector.id;operationQuery='';await tick();if(window.matchMedia('(max-width:700px)').matches)detailElement?.scrollIntoView({block:'start',behavior:'smooth'});}
 function checkSession(){if(client&&session!==(localStorage.getItem('token')||''))lost();}function storage(e:StorageEvent){if(e.key==='token'||e.key===null)lost();}
 onMount(()=>{mounted=true;window.addEventListener('storage',storage);const timer=setInterval(checkSession,500);return()=>clearInterval(timer);});onDestroy(()=>{reset();window.removeEventListener('storage',storage);});
</script>
<section class="starli-automations catalog" aria-label="Starli Integrations catalog"><button class="back" on:click={()=>dispatch('close')}>← Back to workspace</button><header class="sa-heading"><div><span class="sa-eyebrow">COMPANY INTEGRATIONS</span><h1>Starli Integrations</h1><p class="sa-muted">Find business apps, triggers and data tools. Availability reflects this company’s reviewed execution support.</p></div><button disabled={loading} on:click={()=>void load()}>Refresh</button></header><div class="catalog-note"><strong>A listing is not a working connection</strong><p class="sa-muted">Available actions use reviewed native capabilities. Other listings need an account, platform setup or an execution adapter before bots can use them.</p></div>{#if error}<p class="sa-error" role="alert">{error}</p>{/if}
 {#if loading&&!catalog}<p class="sa-muted" role="status">Loading the company integration catalog…</p>{:else if catalog}<div class="filters"><label class="sa-label">Search apps and actions<input class="sa-input" type="search" bind:value={query} on:input={()=>shown=60} placeholder="Shopify, Slack, images, contacts…"/></label><label class="sa-label">Availability<select class="sa-input" bind:value={status} on:change={()=>shown=60}><option value="ALL">All listings</option>{#each INTEGRATION_STATUSES as value}<option value={value}>{integrationLabel[value]}</option>{/each}</select></label></div><p class="sa-muted counts">{filtered.length.toLocaleString()} of {connectors.length.toLocaleString()} listings · {connectors.reduce((sum,c)=>sum+c.operations.length,0).toLocaleString()} listed actions</p><div class="layout" class:has-selection={!!selected}><div><div class="grid">{#each filtered.slice(0,shown) as connector}<button class="connector" class:chosen={selectedId===connector.id} on:click={()=>choose(connector)}><div class="sa-heading"><span class="app-symbol" aria-hidden="true">{catalogText(connector.title).slice(0,1)}</span><span class="sa-badge" class:available={connector.executionStatus==='AVAILABLE'}>{integrationLabel[connector.executionStatus]}</span></div><strong>{catalogText(connector.title)}</strong><p>{catalogText(connector.description)||'Integration capability listing.'}</p><small>{connector.operations.length} listed actions · {connector.kind==='trigger'?'Triggers':connector.kind==='transform'?'Data tools':'Actions'}</small></button>{:else}<div class="sa-empty"><h3>No matching integrations</h3><p class="sa-muted">Try a provider name, action or another availability filter.</p></div>{/each}</div>{#if filtered.length>shown}<button class="more" on:click={()=>shown+=60}>Show more listings</button>{/if}</div><aside class="detail" bind:this={detailElement}>{#if selected}<div class="sa-heading"><div><h2>{catalogText(selected.title)}</h2><p class="sa-muted">{catalogText(selected.description)}</p></div><button aria-label="Close integration details" on:click={()=>selectedId=''}>×</button></div><p class="sa-badge detail-status">{integrationLabel[selected.executionStatus]}</p>{#if selected.executionStatus==='AVAILABLE'}<p class="sa-muted">Reviewed execution support is available. Each action still follows company permissions and any required approval.</p>{:else if selected.executionStatus==='CONNECTION_REQUIRED'}<p class="sa-muted">Connect an authorized company account through its native setup card before use.</p>{:else if selected.executionStatus==='PLATFORM_SETUP_REQUIRED'}<p class="sa-warning">Platform setup is required before this integration can be connected. A listing does not grant access.</p>{:else}<p class="sa-warning">These actions are catalog metadata. They cannot be executed through Starli yet.</p>{/if}<label class="sa-label">Find a listed action<input class="sa-input" type="search" bind:value={operationQuery} placeholder="Create, search, send…"/></label><div class="operations">{#each operations as operation}<article><div class="sa-heading"><strong>{catalogText(operation.title)}</strong><span class="sa-badge">{integrationLabel[operation.executionStatus||'NOT_EXECUTABLE']}</span></div>{#if operation.resource&&operation.resource!=='default'}<small>{catalogText(operation.resource.replace(/([a-z])([A-Z])/g,'$1 $2'))}</small>{/if}{#if operation.description}<p class="sa-muted">{catalogText(operation.description)}</p>{/if}</article>{:else}<p class="sa-muted">{operationQuery?'No matching actions.':'No individual action metadata was provided for this listing.'}</p>{/each}</div>{:else}<div class="sa-empty"><h3>Explore an integration</h3><p class="sa-muted">Select an app or data tool to inspect its listed actions and current availability.</p></div>{/if}</aside></div>{/if}</section>
<style>.catalog{width:100%;max-width:1400px;margin:0 auto;padding:36px 36px 60px;overflow:auto}.back{border:0!important;background:none!important;padding:0!important;color:#71809a!important}header{margin:30px 0 22px}.catalog-note{padding:16px 18px;background:#f6f8fc;border:1px solid #e6ebf4;border-radius:10px}.filters{display:grid;grid-template-columns:minmax(0,2fr) minmax(180px,1fr);gap:16px;margin-top:16px}.counts{font-size:10px!important}.layout{display:grid;grid-template-columns:minmax(0,1.5fr) minmax(280px,1fr);gap:20px;margin-top:16px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.catalog .connector{display:block;min-width:0;text-align:left;padding:16px;border:1px solid #e6ebf4;white-space:normal}.connector.chosen{border-color:#a8bfff;background:#f8faff}.app-symbol{display:grid;place-items:center;width:30px;height:30px;border-radius:8px;background:#edf2ff;color:#3466f6;font-size:14px}.connector>strong{display:block;font-size:13px;margin:14px 0 7px}.connector>p{font-size:11px;color:#71809a;line-height:1.8;margin:0;display:-webkit-box;-webkit-line-clamp:3;line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}.connector>small{display:block;color:#71809a;font-size:9px;margin-top:14px}.sa-badge.available{color:#16765d;border-color:#cfebdf;background:#eff9f4}.detail{border:1px solid #e6ebf4;border-radius:12px;padding:20px;min-width:0;align-self:start;position:sticky;top:0;max-height:calc(100vh - 100px);overflow:auto}.detail-status{display:inline-block;margin:14px 0 5px}.operations article{border-top:1px solid #e6ebf4;padding:14px 0}.operations article .sa-heading{align-items:flex-start}.operations article strong{line-height:1.7}.operations article small{display:block;font-size:9px;color:#71809a;margin-top:6px}.operations .sa-badge{white-space:normal;text-align:right}.detail>.sa-empty{border:0;margin:0;padding:30px 5px}.more{margin-top:16px}.connector .sa-heading{gap:8px}.connector .sa-badge{font-size:8px;white-space:normal;text-align:right}@media(max-width:1000px){.grid{grid-template-columns:1fr}}@media(max-width:700px){.catalog{padding:26px 20px}.layout{grid-template-columns:1fr}.grid{grid-template-columns:1fr}.filters{grid-template-columns:1fr;gap:0}.detail{position:static;max-height:none}.layout.has-selection .detail{order:-1}.catalog h1{font-size:24px}header{flex-direction:column}.connector>p{-webkit-line-clamp:2;line-clamp:2}}</style>
